from format_lecon import Lesson,paras,steps,table
from diagnostics import comparison
from medicaments import xylometazoline
l=Lesson('Obstruction nasale')
l.add('L’obstruction nasale est une {difficulté ressentie à respirer par le nez}. Elle peut être uni- ou bilatérale, intermittente ou permanente. Le symptôme ne précise pas à lui seul le mécanisme.',paras('Distinguer gonflement muqueux, sécrétions, réduction anatomique du passage et lésion occupant la cavité. Une anomalie visible peut être asymptomatique ; l’examen doit être confronté au côté gênant, au retentissement et à l’évolution.', 'L’obstruction peut coexister avec rhinorrhée, perte d’odorat, douleur ou épistaxis. Une gêne nasale n’explique pas automatiquement toute dyspnée : respiration, état général et signes associés restent prioritaires.'),(1,2,6,9))
l.add('Le {contexte dépend fortement de l’âge et de la chronologie}. Rhinites et anomalies structurelles sont des causes usuelles. Chez l’enfant, végétations et corps étrangers sont importants ; chez le nouveau-né, une obstruction bilatérale peut menacer la respiration.',paras('Les dix diagnostics retenus constituent une sélection pédagogique, sans classement suisse de fréquence inventé. Elle n’exclut pas hypertrophie des cornets, dysfonction de valve nasale, rhinite non allergique, cause dentaire, autre masse ou maladie systémique.', 'Une obstruction unilatérale persistante chez l’adulte appelle une exploration. Une masse du rhinopharynx ou une lésion vasculaire ne doit pas être considérée comme une simple végétation sur la seule apparence.'),(1,2,3,4,8,10,11,13))
an=l.subwindow('anatomie','Passage de l’air, muqueuse et obstacle postérieur',paras('La cloison sépare les fosses nasales ; cornets et muqueuse participent au conditionnement de l’air. Un gonflement inflammatoire réduit l’espace disponible sans correspondre à une déviation osseuse ou cartilagineuse.', 'Les choanes sont les ouvertures postérieures vers le rhinopharynx. Une atrésie les obstrue de manière congénitale, tandis que le tissu adénoïdien augmenté peut gêner le passage dans le rhinopharynx.', 'Un hématome septal décolle la muqueuse et compromet la nutrition du cartilage. Il expose à nécrose et abcès : son mécanisme et son urgence diffèrent de l’œdème banal après un coup.', 'Dans l’allergie, l’inflammation médiée par les IgE favorise notamment l’œdème. Un vasoconstricteur peut diminuer temporairement une composante muqueuse, mais son usage prolongé peut provoquer une congestion rebond.'),(2,3,4,5,6,10,11,14))
l.add('Les {bases anatomiques et inflammatoires} orientent le traitement. Un spray peut agir sur une muqueuse sans redresser une cloison. Une collection septale ou une obstruction congénitale répond à une autre démarche.',paras(an),(1,2,4,5,6,14))
l.add('Les {urgences doivent être reconnues avant un traitement d’essai}. Une détresse du nouveau-né, un hématome de cloison ou un objet dangereux impose une prise en charge immédiate. Les signes oculaires, neurologiques et hémorragiques restent prioritaires.',table(['🚩 Présentation','Action'],[['Nouveau-né avec détresse, cyanose, pauses ou alimentation compromise.','Stabilisation respiratoire et équipe néonatale ; 144 si urgence hors hôpital.'],['Obstruction après traumatisme, tuméfaction molle de la cloison.','Avis ORL urgent pour hématome ; ne pas attendre la diminution de l’œdème externe.'],['Pile bouton ou aimants opposés.','Extraction urgente par une équipe compétente.'],['Baisse visuelle, déficit, méningisme, trouble de conscience, état général sévère.','Évaluation hospitalière urgente.'],['Saignement important mal toléré ou menace des voies aériennes.','Prise en charge d’urgence et stabilisation.'],['Masse ou symptômes unilatéraux persistants, sanglants ou progressifs.','Exploration spécialisée rapide, sans attente devant alarme.']]),(4,5,8,11,13))
l.add('L’{anamnèse décrit la gêne et son retentissement}. Préciser côté, ancienneté, variation, déclencheurs et symptômes associés. Demander sommeil, ronflement, alimentation chez l’enfant et traitements déjà utilisés.',paras('Rechercher prurit, éternuements, rhinorrhée, odorat, fièvre, douleur faciale ou dentaire, épistaxis et manifestations oculaires. Noter traumatisme, chirurgie, début dès la naissance et exposition professionnelle.', 'Pour chaque spray, relever nom, concentration, fréquence et durée. Demander asthme, réaction aux anti-inflammatoires, gêne auditive ou otites chez l’enfant. Des pauses respiratoires rapportées pendant le sommeil doivent être évaluées, sans déduire leur gravité du seul volume des végétations.'),(1,3,4,5,6,9,10,13,14))
l.add('L’{examen confronte perméabilité et anatomie}. Il observe nez externe, fosses nasales et muqueuse. L’examen général et les régions associées sont adaptés à l’histoire.',paras('La rhinoscopie recherche déviation, cornets augmentés, sécrétions, polypes, corps étranger et tuméfaction septale. Après traumatisme, l’inspection interne est indispensable même si l’aspect extérieur semble rassurant.', 'L’endoscopie spécialisée explore les régions mal visibles, les choanes et le rhinopharynx. Chez l’enfant, examiner aussi oreilles, amygdales et retentissement respiratoire ; éviter les gestes aveugles devant une masse ou un objet.'),(1,2,3,4,5,8,10,11,13))
l.add('Le {tableau différentiel} associe causes fréquentes et causes à ne pas manquer. Plusieurs mécanismes peuvent coexister. Une amélioration sous traitement ne prouve pas une cause unique.',comparison(),(1,2,3,4,5,6,8,9,10,11,13,14))
l.add('Le {diagnostic positif dépend de la cause}. Le caractère fixe, inflammatoire ou post-traumatique oriente. Les critères d’une rhinosinusite chronique ne sont pas ceux d’une simple obstruction anatomique.',paras('Une déviation septale est pertinente si elle concorde avec la gêne et l’examen ; sa présence seule n’impose pas une opération. Une rhinite allergique repose sur histoire compatible, avec tests ciblés si utiles.', 'Une rhinosinusite chronique associe au moins douze semaines de symptômes compatibles et une confirmation objective. La forme avec polypes habituelle est bilatérale à l’endoscopie ; une masse unilatérale atypique exige une autre exploration.', 'L’hypertrophie adénoïdienne est appréciée selon obstruction, sommeil, audition et examen rhinopharyngé. Une atrésie choanale bilatérale chez le nouveau-né impose d’abord de maintenir une voie aérienne ; le bilan ne doit pas retarder cette étape.'),(1,3,4,6,9,10,11))
l.add('Les {examens complémentaires sont ciblés}. Un nez bouché ne justifie pas automatiquement un scanner. Endoscopie, imagerie, tests allergologiques et explorations du sommeil répondent à des questions différentes.',table(['Question','Examen et limite'],[['Cause inflammatoire ou structurelle ?','Examen nasal et endoscopie selon visibilité et persistance.'],['Allergie cliniquement responsable ?','Tests cutanés ou IgE spécifiques ciblés ; sensibilisation seule insuffisante.'],['Atrésie des choanes ?','Endoscopie et scanner pour confirmation et planification, après stabilisation si détresse.'],['Masse suspecte ?','Imagerie puis biopsie organisée selon le risque ; pas de geste aveugle.'],['Retentissement adénoïdien ?','Évaluation oreilles/audition et sommeil selon le contexte.'],['Traumatisme isolé du nez ?','Diagnostic essentiellement clinique ; imagerie si lésion associée ou question particulière.']]),(1,3,4,5,6,10,11,13))
l.add('L’{algorithme} commence par la sécurité respiratoire et les causes urgentes. Il distingue ensuite mécanisme inflammatoire et obstacle structurel. La persistance ou l’échec justifie une nouvelle évaluation.',steps('Écarter détresse, hématome septal, pile bouton et complications oculaires ou neurologiques.', 'Préciser côté, durée, âge de début, exposition et médicaments.', 'Examiner nez et régions associées ; adresser pour endoscopie ou bilan ciblé si nécessaire.', 'Traiter la composante identifiée et vérifier technique, indication et observance.', 'Réévaluer retentissement et évolution avant de répéter les prescriptions ou de décider une intervention.'),(1,3,4,5,6,8,10,11,13))
med=xylometazoline(l)
l.add('La {prise en charge suisse traite la cause et le retentissement}. Soins locaux, traitement anti-inflammatoire ou chirurgie ont des indications différentes. Une obstruction prolongée n’autorise pas un vasoconstricteur prolongé.',paras('Les soins salins sont adaptés à l’âge, à la cause et au contexte opératoire. Pour un lavage, utiliser une solution appropriée et une eau sûre selon le dispositif, notamment bouillie puis refroidie ; nettoyer le matériel. Une suspicion de brèche ou une urgence nasale demande des consignes spécifiques.',med,'L’allergie et la polypose peuvent nécessiter un corticoïde nasal dans son indication propre. L’hypertrophie adénoïdienne peut faire discuter un traitement local hors information professionnelle selon la spécialité ; ne pas lui attribuer automatiquement la dose autorisée pour l’allergie.', 'La septoplastie est discutée si l’obstacle et la gêne concordent. L’essai britannique NAIROS soutient son efficacité chez des adultes sélectionnés avec symptômes au moins modérés ; il ne prouve pas que toute déviation doit être opérée. Les interventions sur végétations ou choanes relèvent d’un bilan pédiatrique adapté.'),(1,2,3,4,6,9,10,11,12,14,15,17))
l.add('La {prévention et le suivi} portent sur expositions, médicaments et fonction. Protéger l’enfant des piles et petits objets. Réévaluer sommeil, audition et alimentation si concernés.',paras('Vérifier bonne technique du spray et durée réelle des vasoconstricteurs. Les symptômes respiratoires nocturnes persistent parfois malgré un traitement nasal ; leur évaluation ne doit pas être abandonnée.', 'Après chirurgie, respecter les soins et contrôles de l’équipe. Saignement important, douleur inhabituelle, fièvre, obstruction qui s’aggrave ou écoulement aqueux suspect justifient une réévaluation ; ne pas tout attribuer à une cicatrisation normale.'),(2,3,4,5,8,10,14,17))
l.add('Le {point clé} est de distinguer gonflement muqueux et obstacle nécessitant une autre prise en charge. Le retentissement compte autant que l’anatomie. Une urgence ne doit jamais attendre l’effet d’un spray.',paras('Une déviation visible peut être sans rapport avec la plainte, et une obstruction après traumatisme peut cacher un hématome urgent. Le diagnostic et le plan de suivi restent ouverts à l’évolution.'),(1,2,4,5,6,8,10,11))
l.quiz([
('Une déviation visible impose-t-elle toujours une opération ?','Non, elle doit être confrontée aux symptômes et au retentissement.'),
('Quel âge rend une obstruction bilatérale particulièrement préoccupante ?','La période néonatale, notamment si respiration ou alimentation sont compromises.'),
('Que rechercher dans le nez après traumatisme ?','Un hématome de la cloison, en plus des autres lésions.'),
('Peut-on attendre la baisse de l’œdème externe si un hématome septal est suspecté ?','Non, il nécessite un avis urgent.'),
('Quelle information sur les sprays est indispensable ?','Nom, concentration, fréquence et durée réelle.'),
('Pourquoi un vasoconstricteur prolongé peut-il aggraver la gêne ?','Il peut entraîner une congestion rebond et une rhinite médicamenteuse.'),
('Quels éléments évoquent l’allergie ?','Prurit, éternuements et symptômes concordants avec une exposition.'),
('Quel retentissement rechercher chez l’enfant avec végétations ?','Sommeil, respiration buccale, audition et infections associées.'),
('Une masse unilatérale est-elle automatiquement une polypose banale ?','Non.'),
('Faut-il un scanner pour chaque nez bouché ?','Non, l’examen répond à une indication précise.'),
('Devant une atrésie bilatérale avec détresse, que faire avant le bilan complet ?','Sécuriser la respiration avec l’équipe compétente.'),
('Une pile bouton nasale peut-elle attendre un traitement médical ?','Non, elle doit être extraite en urgence.'),
('Un spray redresse-t-il une cloison déviée ?','Non, il peut seulement agir sur une composante muqueuse selon son indication.'),
('L’essai de septoplastie chez des adultes sélectionnés s’applique-t-il à toute déviation ?','Non.')
],(1,2,3,4,5,6,8,9,10,11,12,14))
l.write()
